const pageFor=number=>FLEXIBILITY_PAGES.find(page=>number>=page.from&&number<=page.to);
const make=(number,zone,description,config={})=>{
  const page=pageFor(number),laterality=config.laterality||'bilateral';
  return Object.freeze({
    id:`n${number}`,number,name:`n${number}`,zoneLabel:zone,primaryZone:config.primaryZone||zone,
    secondaryZones:config.secondaryZones||[],page:page.page,bookPage:page.bookPage,pageAsset:page.asset,
    laterality,unilateral:laterality==='sides',sides:laterality==='sides'?['left','right']:[],
    minUseful:config.minUseful,targetDuration:config.targetDuration,maxUseful:config.maxUseful,
    description,shortInstruction:config.shortInstruction||description,detailedInstruction:[description],
    mainMistake:config.mainMistake||'Forcer l’amplitude, rebondir ou retenir la respiration.',
    stopCriterion:config.stopCriterion||'Arrête en cas de douleur vive, de fourmillement ou de perte de contrôle.',
    equipment:config.equipment||[],restPool:config.restPool||null,
    usableAsRestMobility:Boolean(config.restPool),restPrescription:config.restPrescription||null,
    setupCost:config.setupCost||'low',fatigueCost:'very_low',
    avoidBeforeFamilies:config.avoidBeforeFamilies||[],avoidAfterFamilies:config.avoidAfterFamilies||[],
    tags:config.tags||[],type:'canonical',sourceContext:'flexibility'
  });
};

const rest=(target=12,min=10,max=15)=>({minUseful:min,targetDuration:target,maxUseful:max});
const sides={laterality:'sides'};

export const FLEXIBILITY_CATALOG=Object.freeze(Object.fromEntries([
  make(1,'Bras · épaules · haut du dos','Entrecroise les doigts au-dessus de la tête, paumes tournées vers le plafond. Tends les bras vers le haut comme si tu voulais toucher le plafond. Tu dois sentir l’allongement dans les bras et éventuellement entre les omoplates.',{primaryZone:'Épaules / haut du dos',secondaryZones:['Bras'],minUseful:15,targetDuration:25,maxUseful:30,restPool:'standard',restPrescription:rest(),avoidBeforeFamilies:['PH','PV','TV','TH','SC'],tags:['upper','standing']}),
  make(2,'Épaules · bras · haut du dos','Même position que n1, mais garde cette fois les paumes l’une contre l’autre pendant que tu tends les bras vers le haut.',{primaryZone:'Épaules / haut du dos',secondaryZones:['Bras'],minUseful:15,targetDuration:25,maxUseful:30,restPool:'standard',restPrescription:rest(),avoidBeforeFamilies:['PH','PV','TV','TH','SC'],tags:['upper','standing']}),
  make(3,'Épaules · bras','Lève un bras verticalement puis plie-le pour laisser l’avant-bras descendre derrière la tête. Remonte l’autre bras derrière le dos et cherche à rapprocher les deux mains. Inverse ensuite les bras. Si les mains sont trop éloignées, utilise une serviette entre elles et rapproche-les progressivement.',{...sides,primaryZone:'Épaules / bras',minUseful:15,targetDuration:20,maxUseful:30,equipment:['Serviette optionnelle'],restPool:'conditional',restPrescription:rest(),avoidBeforeFamilies:['PH','PV','TV','GR','SC'],tags:['upper','standing']}),
  make(4,'Épaules · poitrine · poignets','Debout, bras le long du corps, remonte les avant-bras derrière le dos et cherche progressivement à rapprocher les paumes jusqu’à les mettre en contact. Pousse doucement en respirant calmement.',{primaryZone:'Épaules / poitrine / poignets',minUseful:15,targetDuration:25,maxUseful:30,restPool:'conditional',restPrescription:rest(),avoidBeforeFamilies:['PH','PV','TV','TH','GR','SC'],tags:['upper','standing']}),
  make(5,'Épaules · dorsaux · tronc','Suspends-toi à une barre fixe. Si tes pieds touchent le sol, plie les jambes : soit en ramenant les genoux vers la poitrine, soit les talons vers les fesses, en alternant les deux positions. Si la suspension complète est trop difficile, garde les orteils légèrement en contact avec le sol pour réduire la charge.',{primaryZone:'Épaules / dorsaux / grip',secondaryZones:['Tronc'],minUseful:10,targetDuration:20,maxUseful:30,equipment:['Barre'],setupCost:'high',avoidBeforeFamilies:['TV','TH','GR','SC'],tags:['upper','trunk','bar'],mainMistake:'Transformer la position en exercice de grip ou rester suspendu malgré une prise qui glisse.'}),
  make(6,'Épaules · poitrine · dorsaux','Place-toi debout sous une barre située derrière toi, les pieds espacés d’environ 35 cm. Attrape la barre bras derrière le corps, d’abord paumes tournées vers le plafond. Recule les pieds puis plie progressivement les jambes jusqu’à sentir l’étirement dans les épaules. Recommence ensuite avec les paumes tournées vers le sol pour déplacer davantage l’étirement vers le haut de la poitrine. Si la barre est trop haute, utilise un support plutôt que de forcer.',{primaryZone:'Épaules / poitrine / dorsaux',minUseful:15,targetDuration:25,maxUseful:30,equipment:['Barre'],setupCost:'high',avoidBeforeFamilies:['PH','PV','TV','TH','SC'],tags:['upper','bar']}),
  make(7,'Flancs · tronc latéral','Debout, pieds un peu plus écartés que les épaules, incline progressivement le buste sur un côté. La main du côté où tu descends glisse le long de la jambe en direction de la cheville. Plus tu descends, plus l’étirement se prolonge le long du flanc vers la taille. Fais ensuite l’autre côté, sans forcer pour atteindre la cheville.',{...sides,primaryZone:'Tronc latéral',minUseful:15,targetDuration:20,maxUseful:30,restPool:'standard',restPrescription:rest(),avoidBeforeFamilies:['AF','ST'],tags:['trunk','standing']}),
  make(8,'Flancs · haut du dos','Reprends le principe de n7, mais assis en tailleur ou en lotus. Incline progressivement le buste sur un côté, puis sur l’autre. Cette position fait davantage ressentir l’étirement vers la partie supérieure du dos.',{...sides,primaryZone:'Tronc latéral / haut du dos',minUseful:15,targetDuration:20,maxUseful:30,setupCost:'medium',avoidBeforeFamilies:['AF','ST'],tags:['upper','trunk','floor']}),
  make(9,'Tronc · poitrine · allongement global','Allonge-toi sur le dos. Tends les bras derrière la tête et les jambes dans la direction opposée, comme si tes mains et tes pieds cherchaient à s’éloigner le plus possible les uns des autres. Respire profondément pour accentuer l’allongement des côtés du corps et de la poitrine.',{primaryZone:'Tronc / poitrine',secondaryZones:['Allongement global'],minUseful:15,targetDuration:25,maxUseful:30,restPool:'conditional',restPrescription:rest(),setupCost:'medium',avoidBeforeFamilies:['PH','PV','AF','ST'],tags:['upper','trunk','floor']}),
  make(10,'Cou','Assis ou debout, garde le buste droit et incline progressivement la tête sur un côté. Cherche l’étirement à la base latérale du cou, et non sous l’oreille à la base du crâne. Reviens au centre puis fais l’autre côté. Si nécessaire, assieds-toi sur une chaise et tiens ses bords pour stabiliser les épaules.',{...sides,primaryZone:'Cou',minUseful:8,targetDuration:10,maxUseful:15,equipment:['Chaise optionnelle'],restPool:'standard',restPrescription:rest(10,8,15),avoidBeforeFamilies:['TV','TH','PV','SC'],tags:['upper','chair','standing']}),
  make(11,'Nuque','Allonge-toi sur le dos, genoux pliés. Entrecroise les doigts derrière la nuque puis accompagne progressivement la tête vers l’avant jusqu’à sentir une tension agréable le long de la nuque. Les mains guident le mouvement : ne tire jamais fortement.',{primaryZone:'Nuque',minUseful:8,targetDuration:10,maxUseful:15,setupCost:'medium',avoidBeforeFamilies:['TV','TH','PV','SC'],tags:['upper','floor'],mainMistake:'Tirer sur la tête avec les bras ou chercher une grande amplitude.'}),
  make(12,'Épaules · chaîne postérieure','Reprends la position des mains de n4, paumes rapprochées derrière le dos. Place une jambe devant toi et garde-la tendue, puis penche le buste vers l’avant avec l’intention de rapprocher la poitrine de la cuisse. Essaie de garder les mains jointes pendant la descente. Fais ensuite la même chose avec l’autre jambe devant.',{...sides,primaryZone:'Épaules + chaîne postérieure',minUseful:15,targetDuration:25,maxUseful:30,avoidBeforeFamilies:['PH','PV','JG','CP'],tags:['upper','legs','standing']}),
  make(13,'Fessier profond · hanche · rotation du tronc','Assieds-toi au sol, tends la jambe droite et plie la gauche en plaçant le pied gauche contre le genou droit. Pose le coude droit contre le genou gauche puis tourne le buste en plaçant la main gauche derrière toi. Utilise doucement le coude pour pousser le genou et accentuer la rotation. Tu dois surtout sentir l’étirement dans le fessier profond. Inverse ensuite les jambes et les bras.',{...sides,primaryZone:'Fessier / hanche / rotation tronc',minUseful:20,targetDuration:25,maxUseful:40,setupCost:'medium',avoidBeforeFamilies:['JG','CP','HA','ST'],tags:['trunk','hips','floor']}),
  make(14,'Poignets · avant-bras','Mets-toi à quatre pattes. Tourne les mains pour que les doigts pointent vers tes genoux, paumes au sol. Recule ensuite progressivement le bassin en pliant les jambes jusqu’à sentir l’étirement dans les avant-bras.',{primaryZone:'Poignets / avant-bras',minUseful:10,targetDuration:15,maxUseful:20,restPool:'conditional',restPrescription:rest(),setupCost:'medium',avoidBeforeFamilies:['TV','TH','PH','PV','GR'],tags:['upper','floor']}),
  make(15,'Poignet · avant-bras','Pose un coude sur la cuisse. Avec l’autre main, saisis le dessus de la main du bras posé et applique une pression modérée pour augmenter progressivement la flexion du poignet. Inverse ensuite les bras. Avec le temps, la mobilité des doigts doit permettre au poignet de se plier davantage.',{...sides,primaryZone:'Poignets / avant-bras',minUseful:10,targetDuration:15,maxUseful:20,restPool:'standard',restPrescription:rest(),avoidBeforeFamilies:['TV','TH','PH','PV','GR'],tags:['upper','chair']}),
  make(16,'Hanche · fessier','Allonge-toi sur le dos. Saisis un genou à deux mains et ramène-le doucement vers la poitrine tout en gardant l’autre jambe tendue au sol. Repose la jambe puis change de côté.',{...sides,primaryZone:'Hanche / fessier',minUseful:20,targetDuration:25,maxUseful:40,restPool:'standard',restPrescription:rest(),setupCost:'medium',avoidBeforeFamilies:['JG','CP','HA'],tags:['hips','legs','floor']}),
  make(17,'Ischio-jambiers','Assieds-toi dans la position montrée sur la page, une jambe tendue et l’autre repliée. Penche-toi vers l’avant et fais progresser les mains le long de la jambe tendue. L’objectif à terme est de pouvoir saisir le pied et rapprocher la poitrine de la cuisse, mais descends seulement jusqu’à ton amplitude actuelle. Change ensuite de jambe.',{...sides,primaryZone:'Ischio-jambiers',minUseful:20,targetDuration:30,maxUseful:40,setupCost:'medium',avoidBeforeFamilies:['JG','CP'],tags:['hips','legs','floor']}),
  make(18,'Ischio-jambiers · hanche','Reprends n17, avec le même travail vers la jambe tendue, mais repousse davantage la jambe pliée vers l’arrière. Cela ajoute un étirement au niveau de la hanche du côté de la jambe repliée. Recule cette jambe seulement autant que la position reste confortable.',{...sides,primaryZone:'Ischio-jambiers + hanche',minUseful:20,targetDuration:30,maxUseful:40,setupCost:'medium',avoidBeforeFamilies:['JG','CP','HA'],tags:['hips','legs','floor']}),
  make(19,'Chaîne postérieure','Debout, jambes légèrement pliées, penche-toi vers l’avant et descends les mains vers le sol. Si possible, pose progressivement les paumes à plat. Une fois cette position confortable, tends peu à peu les jambes tout en essayant de garder les paumes au sol. Ne cherche pas à tendre les jambes d’un seul coup.',{primaryZone:'Chaîne postérieure',minUseful:20,targetDuration:30,maxUseful:40,avoidBeforeFamilies:['JG','CP'],tags:['trunk','legs','standing']}),
  make(20,'Chaîne postérieure · tronc latéral','Reprends la position générale de n19, mais au lieu de descendre uniquement vers l’avant, déplace progressivement le buste vers un côté puis vers l’autre. Alterne côté droit et côté gauche.',{...sides,primaryZone:'Chaîne postérieure + tronc',minUseful:20,targetDuration:25,maxUseful:40,avoidBeforeFamilies:['JG','CP','AF','ST'],tags:['trunk','legs','standing']}),
  make(21,'Hanches · dos','Assieds-toi en tailleur et incline progressivement le buste vers l’avant en gardant les fesses au sol. Commence par poser les mains, puis cherche avec le temps à rapprocher les coudes du sol et ensuite le front. Quand la position devient facile, tu peux entrecroiser les mains derrière la tête pour augmenter légèrement le poids du haut du corps, sans tirer sur la nuque.',{primaryZone:'Hanches / dos',minUseful:20,targetDuration:30,maxUseful:40,setupCost:'medium',avoidBeforeFamilies:['JG','CP','HA','ST'],tags:['trunk','hips','floor']}),
  make(22,'Aine · fléchisseurs de hanche','Pose un genou au sol et avance l’autre pied devant toi. Fais glisser le genou arrière le plus loin possible vers l’arrière tout en gardant le buste droit. Fléchis ensuite davantage la jambe avant pour faire avancer et descendre le bassin simultanément. Tu dois sentir l’étirement dans l’aine. Fais les deux côtés et utilise un coussin sous le genou si nécessaire.',{...sides,primaryZone:'Fléchisseurs hanche / aine',minUseful:20,targetDuration:25,maxUseful:40,equipment:['Coussin optionnel'],restPool:'conditional',restPrescription:rest(),setupCost:'medium',avoidBeforeFamilies:['JG','CP','HA'],tags:['hips','legs','floor']}),
  make(23,'Fléchisseurs de hanche · ischio-jambiers','Reprends n22. Lorsque le genou avant arrive approximativement à la verticale du pied, fais progressivement glisser ce pied vers l’avant pour augmenter l’écartement des jambes. Descends seulement jusqu’à une tension forte mais contrôlée, sans chercher la douleur. Change ensuite de côté. Deux chaises peuvent servir d’appui pour garder le buste droit et contrôler la descente.',{...sides,primaryZone:'Fléchisseurs hanche + ischio-jambiers',minUseful:20,targetDuration:30,maxUseful:40,equipment:['Chaises optionnelles'],setupCost:'high',avoidBeforeFamilies:['JG','CP','HA'],tags:['hips','legs','chair','floor'],stopCriterion:'Arrête avant toute douleur : seule une tension forte mais contrôlée est acceptable.'}),
  make(24,'Adducteurs · aine','Allonge-toi sur le dos et aide les jambes à s’écarter progressivement comme indiqué sur la page. Garde en permanence le bas du dos collé au sol : ne creuse pas les reins. N’ouvre les jambes que jusqu’à l’amplitude que tu peux conserver sans décoller le bas du dos.',{laterality:'alternating',primaryZone:'Adducteurs / aine',minUseful:20,targetDuration:30,maxUseful:40,restPool:'conditional',restPrescription:rest(),setupCost:'medium',avoidBeforeFamilies:['JG','HA'],tags:['hips','legs','floor']}),
  make(25,'Adducteurs','Debout, penche-toi vers l’avant et pose les paumes à plat au sol. En gardant les mains en appui, écarte progressivement les jambes jusqu’à sentir l’étirement à l’intérieur des cuisses. Une surface lisse facilite le glissement contrôlé des pieds.',{primaryZone:'Adducteurs',minUseful:20,targetDuration:30,maxUseful:40,setupCost:'medium',avoidBeforeFamilies:['JG','HA'],tags:['hips','legs','floor']}),
  make(26,'Adducteurs','Assieds-toi au bord d’une chaise stable, jambes et pieds écartés. Croise les bras puis incline progressivement le buste entre les jambes en cherchant à rapprocher les coudes du sol. Laisse principalement le poids du buste augmenter l’amplitude au fil du temps plutôt que de forcer la descente.',{primaryZone:'Adducteurs',minUseful:20,targetDuration:30,maxUseful:40,equipment:['Chaise'],setupCost:'medium',avoidBeforeFamilies:['JG','HA'],tags:['hips','legs','chair']}),
  make(27,'Hanche · ischio-jambiers','Reprends exactement la position de n18. Cette fois, cherche à descendre davantage le haut du corps vers le sol. Si tu es trop raide pour poser les coudes, commence avec les mains, puis les avant-bras. Au fil des séances, rapproche progressivement les coudes du sol.',{...sides,primaryZone:'Hanche + ischio-jambiers',minUseful:20,targetDuration:30,maxUseful:40,setupCost:'medium',avoidBeforeFamilies:['JG','CP','HA'],tags:['hips','legs','floor']}),
  make(28,'Adducteurs · aine','Mets-toi à genoux sur une surface où tu peux ajuster facilement la position. Écarte largement les cuisses, pose les coudes au sol puis repousse progressivement le bassin vers l’arrière comme si tu voulais t’asseoir entre les mollets. Garde les mollets parallèles entre eux pendant tout le mouvement.',{primaryZone:'Adducteurs / aine',minUseful:20,targetDuration:30,maxUseful:40,setupCost:'high',avoidBeforeFamilies:['JG','HA'],tags:['hips','legs','floor']}),
  make(29,'Rotation de la colonne · fessier · ischio-jambiers','Allonge-toi sur le dos, une jambe tendue et l’autre pliée. Fais passer le genou plié de l’autre côté du corps en gardant les épaules collées au sol. Laisse d’abord le poids de la cuisse faire descendre le genou ; une légère pression de la main peut accompagner le mouvement sans forcer. Travaille des deux côtés. Quand le genou peut atteindre le sol confortablement, tu peux progressivement déplier cette jambe et chercher à saisir le pied, puis ramener doucement les orteils vers toi.',{...sides,primaryZone:'Rotation colonne / fessier / ischio-jambiers',minUseful:20,targetDuration:30,maxUseful:40,setupCost:'medium',avoidBeforeFamilies:['JG','CP','ST'],tags:['trunk','hips','legs','floor']}),
  make(30,'Quadriceps','Assieds-toi au sol avec une jambe tendue et l’autre pliée. Le pied de la jambe pliée doit rester dans le prolongement du mollet, avec les orteils dirigés vers l’arrière et non sur le côté. Incline progressivement le buste vers l’arrière : commence par poser au moins un coude au sol et ne descends davantage que lorsque la position devient confortable. Le genou de la jambe pliée doit rester au sol. Fais les deux côtés.',{...sides,primaryZone:'Quadriceps',minUseful:20,targetDuration:25,maxUseful:40,setupCost:'medium',avoidBeforeFamilies:['JG'],tags:['legs','floor'],stopCriterion:'Arrête si le genou de la jambe pliée devient nettement gênant ou douloureux.'}),
  make(31,'Quadriceps · chevilles','Mets-toi à genoux en écartant suffisamment les jambes pour pouvoir descendre le bassin entre les mollets. Commence par essayer de poser les fesses au sol. Quand cette étape devient possible, incline progressivement le buste vers l’arrière : d’abord sur les mains, puis les coudes, puis éventuellement les épaules et le dos. Évite de creuser excessivement les reins. Pour revenir, refais les étapes dans l’ordre inverse.',{primaryZone:'Quadriceps + chevilles',minUseful:20,targetDuration:30,maxUseful:40,setupCost:'high',avoidBeforeFamilies:['JG','MO'],tags:['legs','feet','floor'],stopCriterion:'Arrête en cas de douleur au genou, à la cheville ou dans le bas du dos.'}),
  make(32,'Fessier profond · rotation externe de hanche','Allonge-toi sur le dos près d’un mur. Pose le pied droit à plat contre le mur de façon à garder le mollet droit parallèle au sol. Place l’extérieur de la cheville gauche sur la cuisse droite, près du genou. Tiens la cheville gauche avec la main droite et pousse doucement l’intérieur du genou gauche vers le mur avec l’autre main. Garde le bas du dos collé au sol. Tu dois sentir l’étirement dans la fesse gauche. Inverse ensuite les jambes.',{...sides,primaryZone:'Fessier / hanche',minUseful:20,targetDuration:25,maxUseful:40,equipment:['Mur'],setupCost:'high',avoidBeforeFamilies:['JG','CP','HA'],tags:['hips','legs','floor']}),
  make(33,'Mollet · tendon d’Achille','Prends exactement la position montrée sur la page. Le talon du côté travaillé est légèrement décollé au départ. Penche progressivement le corps vers l’avant sans laisser ce talon se lever davantage. Ensuite, en conservant l’avancée du corps, cherche progressivement à poser le talon au sol sans reculer. Tu dois sentir l’étirement dans le mollet et le tendon d’Achille. Change ensuite de côté.',{...sides,primaryZone:'Mollet / Achille',minUseful:20,targetDuration:25,maxUseful:40,restPool:'conditional',restPrescription:rest(),setupCost:'medium',avoidBeforeFamilies:['MO','JG','CP'],tags:['legs','feet','floor']}),
  make(34,'Mollets','Place le premier tiers de l’avant des pieds sur une cale, une marche ou un barreau stable, avec les talons dans le vide. Descends progressivement les talons vers le bas, comme si tu cherchais à rapprocher les orteils de l’avant des jambes. Tu dois sentir l’étirement dans les mollets.',{primaryZone:'Mollets',minUseful:20,targetDuration:30,maxUseful:40,equipment:['Cale, marche ou barreau'],restPool:'conditional',restPrescription:rest(),setupCost:'high',avoidBeforeFamilies:['MO','JG','CP'],tags:['legs','feet']}),
  make(35,'Dessus du pied · cheville','Place le dessus d’un pied contre le sol comme montré sur la page, puis transfère progressivement un peu de poids dessus pour étirer le dessus du pied. Plie l’autre jambe si nécessaire pour contrôler la pression. Change ensuite de pied.',{...sides,primaryZone:'Pied / cheville',minUseful:10,targetDuration:15,maxUseful:20,restPool:'standard',restPrescription:rest(10,10,15),avoidBeforeFamilies:['MO','JG'],tags:['legs','feet','standing']})
].map(exercise=>[exercise.id,exercise])));

const routine=(id,name,estimate,items,description,notice='')=>Object.freeze({id,name,estimate,items:Object.freeze(items),description,notice});
const item=(id,targetDuration)=>Object.freeze({id,targetDuration});

export const FLEXIBILITY_ROUTINES=Object.freeze({
  complete:routine('complete','Complète','~10–12 min',[item('n1',25),item('n4',25),item('n10',10),item('n7',20),item('n15',15),item('n13',20),item('n17',30),item('n22',25),item('n24',30),item('n30',25),item('n33',25),item('n35',15)],'La référence complète sans empiler les variantes redondantes.'),
  short:routine('short','Complète courte','~5 min',[item('n1',15),item('n7',15),item('n13',15),item('n17',20),item('n22',20),item('n24',20),item('n30',20),item('n33',20)],'Les grandes fonctions avec des durées proches du minimum.'),
  upper:routine('upper','Haut du corps','Ciblée',[item('n1',25),item('n3',20),item('n4',25),item('n7',20),item('n10',10),item('n14',15),item('n15',15)],'Épaules, bras, poitrine, flancs, cou et poignets.'),
  lower:routine('lower','Hanches & jambes','Ciblée',[item('n13',20),item('n16',20),item('n17',30),item('n22',25),item('n24',30),item('n30',25),item('n33',25),item('n35',15)],'Hanches, fessiers, ischios, adducteurs, quadriceps et mollets.'),
  recovery:routine('recovery','Récupération légère','Ciblée',[item('n1',15),item('n7',12),item('n16',15),item('n17',20),item('n22',18),item('n33',18),item('n35',10)],'Des amplitudes faciles et courtes.','Reste loin de ton amplitude maximale.')
});

const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
export const freshFlexibilityState=()=>({history:[],active:null});

export function buildFlexibilityPlan(routineId){
  let definition=FLEXIBILITY_ROUTINES[routineId];
  if(!definition&&routineId.startsWith('explore:')){const id=routineId.slice(8),exercise=FLEXIBILITY_CATALOG[id];if(!exercise)throw Error('Exercice de souplesse inconnu.');definition=routine(routineId,exercise.name,'Libre',[item(id,exercise.targetDuration)],'Exercice libre');}
  if(!definition)throw Error('Routine de souplesse inconnue.');
  return definition.items.flatMap((configured,exerciseIndex)=>{const exercise=FLEXIBILITY_CATALOG[configured.id],target=configured.targetDuration??exercise.targetDuration,base={exerciseId:exercise.id,exerciseIndex:exerciseIndex+1,exerciseTotal:definition.items.length,minUseful:Math.min(exercise.minUseful,target),targetDuration:target,maxUseful:Math.max(exercise.maxUseful,target)};return exercise.unilateral?exercise.sides.map(side=>({...base,side})):[{...base,side:null}];});
}

export function startFlexibility(state,routineId,now=Date.now()){
  if(state.active||state.flexibility?.active)return false;
  const definition=FLEXIBILITY_ROUTINES[routineId]||FLEXIBILITY_CATALOG[routineId.slice(8)];if(!definition)return false;
  const plan=buildFlexibilityPlan(routineId);state.flexibility.active={id:uid(),routineId,routineName:definition.name,sourceContext:'flexibility',startedAt:now,finishedAt:null,status:'active',plan,cursor:0,results:[],timer:null,draft:{rating:'Correct',note:''}};return true;
}

export const currentFlexibilityPosition=state=>state.flexibility?.active?.plan[state.flexibility.active.cursor]||null;
export function elapsedFlexibilityTimer(timer,now=Date.now()){return timer?timer.elapsedMs+(timer.runningSince===null?0:Math.max(0,now-timer.runningSince)):0;}
export function toggleFlexibilityTimer(state,now=Date.now()){const active=state.flexibility?.active;if(!active)return false;if(!active.timer)active.timer={elapsedMs:0,runningSince:now};else if(active.timer.runningSince!==null)active.timer={elapsedMs:elapsedFlexibilityTimer(active.timer,now),runningSince:null};else active.timer.runningSince=now;return true;}
export function flexibilityDurationStatus(position,elapsedSeconds){if(elapsedSeconds>=position.maxUseful)return'max';if(elapsedSeconds>=position.targetDuration)return'target';if(elapsedSeconds>=position.minUseful)return'min';return'before';}

export function previousFlexibilityPosition(state){
  const active=state.flexibility?.active;if(!active||active.cursor<=0)return false;
  const previousIndex=active.cursor-1,found=active.results.findIndex(result=>result.positionIndex===previousIndex),index=found>=0?found:active.results.length-1,result=index>=0?active.results.splice(index,1)[0]:null;
  active.cursor=previousIndex;active.timer=result?{elapsedMs:Math.max(0,Number(result.actualSeconds)||0)*1000,runningSince:null}:null;active.draft={rating:result?.rating||'Correct',note:result?.note||''};return true;
}

export function completeFlexibilityPosition(state,now=Date.now()){
  const active=state.flexibility?.active,position=currentFlexibilityPosition(state);if(!active||!position||!FLEXIBILITY_RATINGS.includes(active.draft.rating))return false;
  const exercise=FLEXIBILITY_CATALOG[position.exerciseId],actualSeconds=Math.round(elapsedFlexibilityTimer(active.timer,now)/100)/10,result={...position,positionIndex:active.cursor,id:exercise.id,name:exercise.name,actualSeconds,rating:active.draft.rating,note:active.draft.note.trim(),at:now,sourceContext:'flexibility'};
  const existing=active.results.findIndex(entry=>entry.positionIndex===active.cursor);if(existing>=0)active.results[existing]=result;else active.results.push(result);
  active.cursor++;active.timer=null;active.draft={rating:'Correct',note:''};
  if(active.cursor<active.plan.length)return false;
  active.finishedAt=now;active.status='complete';state.flexibility.history.push(active);state.flexibility.active=null;return true;
}

export function abandonFlexibility(state,now=Date.now()){
  const active=state.flexibility?.active;if(!active)return false;active.finishedAt=now;active.status='interrupted';if(active.results.length)state.flexibility.history.push(active);state.flexibility.active=null;return true;
}

export function assertFlexibilityState(value){
  if(!value||!Array.isArray(value.history))throw Error('Historique Souplesse invalide.');
  const sessions=[...value.history,...(value.active?[value.active]:[])];
  for(const session of sessions){
    if(!Array.isArray(session.plan)||!Array.isArray(session.results)||!Number.isFinite(session.startedAt))throw Error('Routine Souplesse invalide.');
    if(session.legacy){for(const result of session.results)if(!Number.isFinite(result.actualSeconds)||typeof result.rating!=='string')throw Error('Résultat Souplesse historique invalide.');continue;}
    if(session.sourceContext!=='flexibility')throw Error('Routine Souplesse invalide.');
    for(const result of session.results)if(!FLEXIBILITY_CATALOG[result.exerciseId||result.id]||!FLEXIBILITY_RATINGS.includes(result.rating)||!Number.isFinite(result.actualSeconds))throw Error('Résultat Souplesse invalide.');
  }
  if(value.active){const active=value.active;if(active.legacy||active.cursor<0||active.cursor>=active.plan.length||!FLEXIBILITY_RATINGS.includes(active.draft?.rating))throw Error('Routine Souplesse active invalide.');for(const position of active.plan)if(!FLEXIBILITY_CATALOG[position.exerciseId]||!(position.minUseful<=position.targetDuration&&position.targetDuration<=position.maxUseful))throw Error('Position Souplesse invalide.');}
  return value;
}
